
button{
    cursor: pointer;

    &:focus{
        outline: 0;
        box-shadow: none;
    }
}

.btn {
	padding: 0.59375rem 1.5rem;
    border-radius: 0.5rem;
    font-weight: 400;
    font-size: 1rem;
    line-height: 1.5;
    &:hover, &:focus, &:active, &.active{
        outline: 0!important;
    }
	
	@include respond('laptop') {
		padding: 0.625rem 1rem;
		font-size: 0.813rem;
	}
	&.btn-success,&.btn-secondary,&.btn-warning,&.btn-primary,&.btn-danger,&.btn-info{
		color:$white;
	}
	
    &-transparent {
        background-color: transparent;
    }
	&.btn-primary,
	&.btn-secondary,
	&.btn-danger,
	&.btn-info,
	&.btn-dark,
	&.btn-success,
	&.btn-warning{
		&:active{
			color:$white!important;
		}
	}



}
.btn-primary{
	border-color:var(--primary);	
	background-color:var(--primary);
	&:active,
	&:focus,
	&:hover{
		border-color:var(--primary-hover);	
		background-color:var(--primary-hover);	
	}
	&:focus{
		box-shadow:0 0 0 0.25rem var(--rgba-primary-5);
	}
	&:disabled,
	&.disabled{
		background-color: var(--primary);
		border-color: var(--primary);
	}
}

.btn-link{
	color:var(--primary);
	text-decoration: none;
	&:hover{
		color:var(--primary-hover);	
	}
}
.btn-outline-primary {
	color:var(--primary);	
	border-color:var(--primary);
	&:hover{
		border-color:var(--primary-hover);	
		background-color:var(--primary-hover);	
	}
}
.sharp {
	min-width: 2.4rem;
    padding: 0.4375rem;
    height: 2.4rem;
    line-height: 1.5;
    min-height: 2.5rem;
}

.sharp.btn-xs{
    padding: 0.1875rem;
    width: 1.625rem;
    height: 1.625rem;
    min-width: 1.625rem;
    min-height: 1.625rem;
}
.sharp-lg{
