.btn-outline-primary:active,
.btn-outline-primary.active,
.btn-outline-primary.dropdown-toggle.show{
	background-color:var(--primary);
	border-color:var(--primary);
	color:$white;
}
 
.btn-check:checked + .btn-outline-primary:focus,
.btn-check:active + .btn-outline-primary:focus,
.btn-outline-primary:active:focus,
.btn-outline-primary.active:focus,
.btn-outline-primary.dropdown-toggle.show:focus{
	box-shadow:0 0 0 0.25rem var(--rgba-primary-5);
}
.btn-check:focus + .btn-outline-primary, .btn-outline-primary:focus{
	box-shadow:0 0 0 0.25rem var(--rgba-primary-5);
}
.btn-close:focus{
	box-shadow:0 0 0 0.25rem var(--rgba-primary-5);
}
.btn-icon-lg {
    padding: 15px 18px;
    min-width: 20px !important;
}
.btn-icon-md {
    padding: 13px 16px;
    min-width: 20px !important;
}
.btn-icon-sm {
    padding: 11px 14px;
    min-width: 20px !important;
}
.btn-icon-xs {
    padding: 10px 12px;
    min-width: 20px !important;
}
.btn-icon-xxs {
    padding: 8px 10px;
    min-width: 20px !important;
}

.btn-close{
	background:none;
	position:relative;
	font-family: "Font Awesome 5 Free";
	margin-#{$dlab-pos-left}: auto !important;
	margin-#{$dlab-pos-right}: unset !important;
	color:var(--text-dark);
	&:before{
		content:'\f00d';
		font-weight: 600;
		
	}
	&:hover{
		color:var(--text-dark);
	}
}

// override bootstrap buttons
.btn-group{
	& > .btn:not(:last-child):not(:first-child):not(.dropdown-toggle){
		border-radius: 0 ;
	}
	& > .btn:not(:last-child):not(.dropdown-toggle){
		border-top-#{$dlab-pos-right}-radius: 0;
		border-bottom-#{$dlab-pos-right}-radius: 0;
		border-top-#{$dlab-pos-left}-radius: $radius;
		border-bottom-#{$dlab-pos-left}-radius: $radius;
	}
	& > .btn.dropdown-toggle-split:first-child, .btn-group > .btn-group:not(:last-child) > .btn{
		border-top-#{$dlab-pos-right}-radius: 0;
		border-bottom-#{$dlab-pos-right}-radius: 0;
		border-top-#{$dlab-pos-left}-radius: $radius;
		border-bottom-#{$dlab-pos-left}-radius: $radius;
	}
	button.dropdown-toggle.dropdown-toggle-split:first-child{
		border-top-#{$dlab-pos-right}-radius: 0 !important;
    	border-bottom-#{$dlab-pos-right}-radius: 0 !important;
		border-top-#{$dlab-pos-left}-radius: $radius !important;
		border-bottom-#{$dlab-pos-left}-radius: $radius !important;
	}
	button.dropdown-toggle.dropdown-toggle-split{
		border-top-#{$dlab-pos-left}-radius: 0 !important;
    	border-bottom-#{$dlab-pos-left}-radius: 0 !important;
		border-top-#{$dlab-pos-right}-radius: $radius !important;
		border-bottom-#{$dlab-pos-right}-radius: $radius !important;
	}
	& > :not(.btn-check) + .btn{
		border-top-#{$dlab-pos-left}-radius: 0;
    	border-bottom-#{$dlab-pos-left}-radius: 0;
		border-top-#{$dlab-pos-right}-radius: $radius;
		border-bottom-#{$dlab-pos-right}-radius: $radius;
	}
	& > .btn-group:not(:first-child) > .btn{
		border-top-#{$dlab-pos-left}-radius: 0;
    	border-bottom-#{$dlab-pos-left}-radius: 0;
		border-top-#{$dlab-pos-right}-radius: $radius;
		border-bottom-#{$dlab-pos-right}-radius: $radius;
	}
}

.dropdown-toggle::after{
	margin: 0;
	margin-#{$dlab-pos-left}: 0.255em;
}
.btn-close{
	&:focus{
		box-shadow:unset;
	}
}
